// The 'audio' service: players whose lifetime is the service's, not the caller's (a player plugin
// is reloaded on every edit; the music goes on). Two backends behind one contract (AudioPlayer in
// types.ts):
//
// - native: the Mac app registers `webkit.messageHandlers.tilrAudio`. A player is an AVPlayer of
//   the app's, named by its key; the page posts { op, id, … } (list, create, load, play, pause,
//   stop, seek, volume, balance, eq, dispose) and the app reports back through a 'tilr-audio'
//   CustomEvent on `window`: a player's full state on every change (not periodically; the page
//   interpolates the position from `{ position, at, rate }`), 'ended', 'error', a media key
//   ('command'), and the answer to 'list'. The app owns the players, so they outlive a reload of
//   the page: on start the service asks for the list and adopts what plays. 'create' is
//   idempotent on the app's side (a live id just reports its state again), so a player asked
//   for before the list comes back is adopted all the same. No EQ, balance or analyser in v1:
//   the values are sent anyway and kept in the page's state.
// - web: anywhere else (a browser, the tests), Webamp's graph: an <audio> element (crossOrigin
//   'anonymous': a cross-origin track must allow CORS, or Web Audio hears silence) → balance
//   (splitter, two gains, merger) → preamp → 10 filters → volume → the speakers, the analyser
//   tapped before the volume. The graph objects (element, AudioContext, nodes) and the player's
//   state live in a holder on `globalThis` (`__tilrAudio`), not in this module: a reload of this
//   plugin starts a new service that re-adopts them (detaching the old module's listeners from
//   the element, attaching its own), and the plugin's own dispose leaves them playing. A page
//   reload ends them. The AudioContext starts suspended without a user gesture: it is resumed on
//   the first pointerdown / keydown, and on every play().
//
// The players are the service's: player(key) registers no effect in the caller. The caller's are
// its listeners (subscribe, on): each is an effect of the plugin that added it, so a reloaded
// consumer leaves no listener behind.
import { Service } from 'cordis'
import type { Context } from 'cordis'
import type { Audio as AudioApi, AudioFeatures, AudioPlayer, AudioState, AudioStatus, TilrPluginClass } from 'tilr'
import { nativeChannel } from 'tilr/native'

/** The app's message handler, and the event it answers with. */
export const HANDLER = 'tilrAudio'
export const EVENT = 'tilr-audio'

/** Winamp's equalizer bands, Hz. */
export const BANDS = [60, 170, 310, 600, 1000, 3000, 6000, 12000, 14000, 16000]

declare global {
  /** The web backend's graphs, kept across reloads of the audio plugin (see the header). */
  var __tilrAudio: Holder | undefined
}

/** What the app reports of a player (`type: 'state'`, and each of a 'list'). `at` is when
 *  `position` was true (Date.now() scale), `rate` 0 or 1. */
export interface AudioReport {
  id: string
  status: AudioStatus
  url: string | null
  position: number
  at: number
  rate: number
  duration: number
  stalled: boolean
  volume: number
}

/** What arrives with a 'tilr-audio' event. */
export type NativeEvent =
  | ({ type: 'state' } & AudioReport)
  | { type: 'ended', id: string }
  | { type: 'error', id: string, message: string }
  | { type: 'command', id: string, command: 'next' | 'previous' }
  | { type: 'list', players: AudioReport[] }

type Listener = () => void
type EventName = 'ended' | 'error' | 'command'
type EventListener = (detail?: unknown) => void

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))
/** A duration as the state has it: 0 until known (NaN, Infinity, null from JSON). */
const known = (seconds: unknown): number => typeof seconds === 'number' && Number.isFinite(seconds) && seconds > 0 ? seconds : 0

/** The state a player starts with. */
export function initial(): AudioState {
  return { status: 'stopped', url: null, position: 0, duration: 0, stalled: false, volume: 1, balance: 0, eq: { enabled: false, preamp: 0, bands: BANDS.map(() => 0) } }
}

/** `eq` with `patch` merged in, clamped to -12 … 12 dB, always 10 bands. */
export function mergeEq(eq: AudioState['eq'], patch: Partial<AudioState['eq']>): AudioState['eq'] {
  const bands = patch.bands ?? eq.bands
  return {
    enabled: patch.enabled ?? eq.enabled,
    preamp: clamp(patch.preamp ?? eq.preamp, -12, 12),
    bands: BANDS.map((_, i) => clamp(bands[i] ?? 0, -12, 12)),
  }
}

const sameEq = (a: AudioState['eq'], b: AudioState['eq']): boolean =>
  a.enabled === b.enabled && a.preamp === b.preamp && a.bands.every((v, i) => v === b.bands[i])

/** A player as the service holds it: its listeners and what a backend does. The callers get a
 *  `Handle` on it. */
abstract class Core {
  readonly key: string
  /** False once disposed, or once the service that made it has gone: it does nothing then. */
  live = true
  private listeners = new Set<Listener>()
  private events = new Map<EventName, Set<EventListener>>()

  constructor(key: string) {
    this.key = key
  }

  abstract readonly state: AudioState
  abstract load(url: string, meta?: { title?: string, artist?: string }): void
  abstract play(): void
  abstract pause(): void
  abstract stop(): void
  abstract seek(seconds: number): void
  abstract setVolume(volume: number): void
  abstract setBalance(balance: number): void
  abstract setEq(eq: Partial<AudioState['eq']>): void
  abstract analyser(): AnalyserNode | null
  /** The backend's part of dispose(). */
  protected abstract close(): void

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  on(event: EventName, listener: EventListener): () => void {
    let set = this.events.get(event)
    if (!set) this.events.set(event, set = new Set())
    set.add(listener)
    return () => { set.delete(listener) }
  }

  notify(): void {
    for (const listener of [...this.listeners]) {
      try { listener() } catch (error) { console.error(error) }
    }
  }

  emit(event: EventName, detail?: unknown): void {
    for (const listener of [...this.events.get(event) ?? []]) {
      try { listener(detail) } catch (error) { console.error(error) }
    }
  }

  /** The service went: the player lives on (the next service adopts it), this object does not. */
  release(): void {
    this.live = false
    this.listeners.clear()
    this.events.clear()
  }

  dispose(): void {
    if (!this.live) return
    this.close()
    this.release()
  }
}

/** What a caller holds: a core, and the caller's context, whose effects its listeners become. */
class Handle implements AudioPlayer {
  private core: Core
  private ctx: Context | null

  constructor(core: Core, ctx: Context | null) {
    this.core = core
    this.ctx = ctx
  }

  get key(): string { return this.core.key }
  get status(): AudioStatus { return this.core.state.status }
  get url(): string | null { return this.core.state.url }
  get position(): number { return this.core.state.position }
  get duration(): number { return this.core.state.duration }
  get stalled(): boolean { return this.core.state.stalled }
  get volume(): number { return this.core.state.volume }
  get balance(): number { return this.core.state.balance }
  get eq(): AudioState['eq'] { return this.core.state.eq }

  load(url: string, meta?: { title?: string, artist?: string }): void { if (this.core.live) this.core.load(url, meta) }
  play(): void { if (this.core.live) this.core.play() }
  pause(): void { if (this.core.live) this.core.pause() }
  stop(): void { if (this.core.live) this.core.stop() }
  seek(seconds: number): void { if (this.core.live) this.core.seek(seconds) }
  setVolume(volume: number): void { if (this.core.live) this.core.setVolume(volume) }
  setBalance(balance: number): void { if (this.core.live) this.core.setBalance(balance) }
  setEq(eq: Partial<AudioState['eq']>): void { if (this.core.live) this.core.setEq(eq) }
  analyser(): AnalyserNode | null { return this.core.live ? this.core.analyser() : null }

  subscribe(listener: () => void): () => void {
    return this.owned(this.core.subscribe(listener), 'audio: subscribe()')
  }

  on(event: EventName, callback: (detail?: unknown) => void): () => void {
    return this.owned(this.core.on(event, callback), `audio: on('${event}')`)
  }

  dispose(): void { this.core.dispose() }

  /** `off` as an effect of the caller, so the listener leaves with it; the returned function
   *  removes it earlier (and the effect with it). A caller that is not running keeps it as is. */
  private owned(off: () => void, label: string): () => void {
    if (!this.ctx) return off
    try {
      const dispose = this.ctx.effect(() => off, label)
      return () => { void dispose() }
    } catch {
      return off
    }
  }
}

// --- native: the app's players ---

/** A player of the app's: the last report, and what the page asked for since. */
export class NativePlayer extends Core {
  private post: (body: Record<string, unknown>) => void
  private now: () => number
  private onClose: (player: NativePlayer) => void
  private base: AudioState = initial()
  /** When `base.position` was true, and how fast it moves since (0 or 1). */
  private at = 0
  private rate = 0

  constructor(key: string, post: (body: Record<string, unknown>) => void, now: () => number, onClose: (player: NativePlayer) => void) {
    super(key)
    this.post = post
    this.now = now
    this.onClose = onClose
  }

  get state(): AudioState {
    return { ...this.base, position: this.position() }
  }

  private position(): number {
    const { status, position, duration } = this.base
    if (status !== 'playing' || !this.rate) return position
    const moved = position + (this.now() - this.at) / 1000 * this.rate
    return duration > 0 ? Math.min(moved, duration) : moved
  }

  /** Merges `patch` (and the position's base) into the state; tells the listeners if anything
   *  but the position moving on changed. */
  apply(patch: Partial<AudioState>, motion?: { position: number, at: number, rate: number }): void {
    const next: AudioState = { ...this.base, ...patch }
    let changed = false
    for (const key of ['status', 'url', 'duration', 'stalled', 'volume', 'balance'] as const) {
      if (next[key] !== this.base[key]) changed = true
    }
    if (!sameEq(next.eq, this.base.eq)) changed = true
    if (motion) {
      // A new base is a change unless it is where the old one says it should be by now.
      if (Math.abs(this.position() - motion.position - (this.now() - motion.at) / 1000 * motion.rate) > 0.05 || motion.rate !== this.rate) changed = true
      next.position = motion.position
      this.at = motion.at
      this.rate = motion.rate
    }
    this.base = next
    if (changed) this.notify()
  }

  /** The app's report. */
  report(report: AudioReport): void {
    this.apply({
      status: report.status,
      url: report.url ?? null,
      duration: known(report.duration),
      stalled: !!report.stalled,
      volume: clamp(report.volume, 0, 1),
    }, { position: Number(report.position) || 0, at: Number(report.at) || this.now(), rate: report.status === 'playing' ? Number(report.rate) || 0 : 0 })
  }

  load(url: string, meta?: { title?: string, artist?: string }): void {
    this.apply({ status: 'stopped', url, duration: 0, stalled: false }, { position: 0, at: this.now(), rate: 0 })
    this.post({ op: 'load', id: this.key, url, ...meta?.title !== undefined && { title: meta.title }, ...meta?.artist !== undefined && { artist: meta.artist } })
  }

  play(): void {
    if (this.base.url === null) return
    if (this.base.status !== 'playing') this.apply({ status: 'playing' }, { position: this.position(), at: this.now(), rate: 1 })
    this.post({ op: 'play', id: this.key })
  }

  pause(): void {
    if (this.base.status === 'playing') this.apply({ status: 'paused' }, { position: this.position(), at: this.now(), rate: 0 })
    this.post({ op: 'pause', id: this.key })
  }

  stop(): void {
    this.apply({ status: 'stopped' }, { position: 0, at: this.now(), rate: 0 })
    this.post({ op: 'stop', id: this.key })
  }

  seek(seconds: number): void {
    const { duration } = this.base
    const position = clamp(seconds, 0, duration > 0 ? duration : Infinity)
    this.apply({}, { position, at: this.now(), rate: this.base.status === 'playing' ? 1 : 0 })
    this.post({ op: 'seek', id: this.key, position })
  }

  setVolume(volume: number): void {
    const v = clamp(volume, 0, 1)
    this.apply({ volume: v })
    this.post({ op: 'volume', id: this.key, volume: v })
  }

  setBalance(balance: number): void {
    const b = clamp(balance, -1, 1)
    this.apply({ balance: b })
    this.post({ op: 'balance', id: this.key, balance: b })
  }

  setEq(patch: Partial<AudioState['eq']>): void {
    const eq = mergeEq(this.base.eq, patch)
    this.apply({ eq })
    this.post({ op: 'eq', id: this.key, ...eq })
  }

  analyser(): null { return null }

  /** The end of the track, told by the app: stopped at 0 (the state that follows says so too). */
  ended(): void {
    this.apply({ status: 'stopped' }, { position: 0, at: this.now(), rate: 0 })
    this.emit('ended')
  }

  protected close(): void {
    this.post({ op: 'dispose', id: this.key })
    this.onClose(this)
  }
}

/** The native backend without the service around it: the players by key, the app's events in.
 *  `post` is the message handler's; `now` the clock (Date.now, a fake one in the tests). */
export class NativeAudio {
  readonly players = new Map<string, NativePlayer>()
  private post: (body: Record<string, unknown>) => void
  private now: () => number

  constructor(post: (body: Record<string, unknown>) => void, now: () => number = Date.now) {
    this.post = post
    this.now = now
  }

  /** Asks the app for the players it has. */
  start(): void {
    this.post({ op: 'list' })
  }

  /** The player `key`: the known one, else a new one the app is asked to create (or to report,
   *  if it has it already). */
  player(key: string): NativePlayer {
    const existing = this.players.get(key)
    if (existing) return existing
    const player = this.adopt(key)
    this.post({ op: 'create', id: key })
    return player
  }

  private adopt(key: string): NativePlayer {
    const player = new NativePlayer(key, this.post, this.now, closed => {
      if (this.players.get(closed.key) === closed) this.players.delete(closed.key)
    })
    this.players.set(key, player)
    return player
  }

  receive(detail: NativeEvent | null | undefined): void {
    if (!detail || typeof detail !== 'object') return
    switch (detail.type) {
      case 'list':
        for (const report of detail.players ?? []) (this.players.get(report.id) ?? this.adopt(report.id)).report(report)
        return
      case 'state':
        // An id the page does not know is the app's all the same: adopted.
        return (this.players.get(detail.id) ?? this.adopt(detail.id)).report(detail)
      case 'ended':
        return this.players.get(detail.id)?.ended()
      case 'error':
        return this.players.get(detail.id)?.emit('error', { message: detail.message })
      case 'command':
        return this.players.get(detail.id)?.emit('command', { command: detail.command })
    }
  }

  /** The service going: the app keeps the players, this page forgets them. */
  release(): void {
    for (const player of this.players.values()) player.release()
    this.players.clear()
  }
}

// --- web: Webamp's graph, kept on globalThis ---

/** One player's graph and state, as kept across reloads of this plugin. Plain data: the module
 *  that adopts it brings its own code. */
interface Graph {
  audio: HTMLAudioElement
  source: MediaElementAudioSourceNode
  /** Where the source goes: into the preamp (EQ on) or straight to the balance (EQ off). */
  input: GainNode
  preamp: GainNode
  filters: BiquadFilterNode[]
  /** The balance: in (an up-mixer to stereo) → splitter → left / right gains → merger. */
  balanceIn: GainNode
  left: GainNode
  right: GainNode
  merger: ChannelMergerNode
  gain: GainNode
  analyserNode: AnalyserNode
  status: AudioStatus
  url: string | null
  duration: number
  stalled: boolean
  volume: number
  balance: number
  eq: AudioState['eq']
  /** Takes the listeners of the module that attached them off the element. */
  detach: (() => void) | null
}

interface Holder {
  context: AudioContext | null
  graphs: Map<string, Graph>
}

function holder(): Holder {
  return globalThis.__tilrAudio ??= { context: null, graphs: new Map() }
}

function context(): AudioContext {
  const h = holder()
  if (!h.context || h.context.state === 'closed') h.context = new AudioContext()
  return h.context
}

/** dB → a gain factor. */
const factor = (db: number): number => 10 ** (db / 20)

function build(key: string): Graph {
  const ctx = context()
  const audio = document.createElement('audio')
  audio.crossOrigin = 'anonymous'
  audio.preload = 'auto'
  audio.dataset.tilrAudio = key
  const source = ctx.createMediaElementSource(audio)
  const input = ctx.createGain()
  const preamp = ctx.createGain()
  const filters = BANDS.map((frequency, i) => {
    const filter = ctx.createBiquadFilter()
    // The ends take everything below / above them, as in Webamp.
    filter.type = i === 0 ? 'lowshelf' : i === BANDS.length - 1 ? 'highshelf' : 'peaking'
    filter.frequency.value = frequency
    filter.gain.value = 0
    return filter
  })
  // A splitter cannot up-mix: a mono track would play left only. A gain with an explicit
  // channel count of 2 makes anything stereo first.
  const balanceIn = ctx.createGain()
  balanceIn.channelCount = 2
  balanceIn.channelCountMode = 'explicit'
  balanceIn.channelInterpretation = 'speakers'
  const splitter = ctx.createChannelSplitter(2)
  const left = ctx.createGain()
  const right = ctx.createGain()
  const merger = ctx.createChannelMerger(2)
  const gain = ctx.createGain()
  const analyserNode = ctx.createAnalyser()
  analyserNode.fftSize = 2048
  analyserNode.smoothingTimeConstant = 0

  source.connect(input)
  let out: AudioNode = preamp
  for (const filter of filters) { out.connect(filter); out = filter }
  out.connect(balanceIn)
  balanceIn.connect(splitter)
  splitter.connect(left, 0)
  splitter.connect(right, 1)
  left.connect(merger, 0, 0)
  right.connect(merger, 0, 1)
  merger.connect(gain)
  merger.connect(analyserNode)
  gain.connect(ctx.destination)

  const state = initial()
  const graph: Graph = { audio, source, input, preamp, filters, balanceIn, left, right, merger, gain, analyserNode, ...state, detach: null }
  route(graph)
  return graph
}

/** The EQ in or out of the chain. */
function route(graph: Graph): void {
  graph.input.disconnect()
  graph.input.connect(graph.eq.enabled ? graph.preamp : graph.balanceIn)
  graph.preamp.gain.value = factor(graph.eq.preamp)
  graph.filters.forEach((filter, i) => { filter.gain.value = graph.eq.bands[i] ?? 0 })
}

function describe(error: MediaError | null): string {
  if (!error) return 'unknown error'
  const name = ['', 'aborted', 'network error', 'cannot decode', 'unsupported source'][error.code] ?? `error ${error.code}`
  return error.message ? `${name}: ${error.message}` : name
}

class WebPlayer extends Core {
  readonly graph: Graph
  private onClose: (player: WebPlayer) => void

  constructor(key: string, graph: Graph, onClose: (player: WebPlayer) => void) {
    super(key)
    this.graph = graph
    this.onClose = onClose
    this.attach()
  }

  get state(): AudioState {
    const { status, url, duration, stalled, volume, balance, eq } = this.graph
    return { status, url, position: this.graph.audio.currentTime || 0, duration, stalled, volume, balance, eq }
  }

  /** This module's listeners on the element, in place of the previous one's. They keep the
   *  graph's state right after this service has gone (until the next one adopts the graph). */
  private attach(): void {
    const g = this.graph
    g.detach?.()
    const set = (patch: Partial<Graph>) => {
      let changed = false
      for (const [key, value] of Object.entries(patch)) {
        if (g[key as keyof Graph] !== value) { Object.assign(g, { [key]: value }); changed = true }
      }
      if (changed && this.live) this.notify()
    }
    const handlers: Record<string, () => void> = {
      durationchange: () => set({ duration: known(g.audio.duration) }),
      loadedmetadata: () => set({ duration: known(g.audio.duration) }),
      waiting: () => set({ stalled: true }),
      playing: () => set({ stalled: false }),
      canplay: () => set({ stalled: false }),
      ended: () => {
        try { g.audio.currentTime = 0 } catch { /* no media */ }
        set({ status: 'stopped', stalled: false })
        if (this.live) this.emit('ended')
      },
      error: () => {
        // Only the current source's errors (a src removed on dispose errors too).
        if (!g.audio.getAttribute('src')) return
        g.audio.pause()
        set({ status: 'stopped', stalled: false })
        if (this.live) this.emit('error', { message: describe(g.audio.error) })
      },
    }
    for (const [name, handler] of Object.entries(handlers)) g.audio.addEventListener(name, handler)
    g.detach = () => { for (const [name, handler] of Object.entries(handlers)) g.audio.removeEventListener(name, handler) }
  }

  private change(patch: Partial<Graph>): void {
    Object.assign(this.graph, patch)
    this.notify()
  }

  load(url: string): void {
    const { audio } = this.graph
    audio.pause()
    audio.src = url
    audio.load()
    this.change({ status: 'stopped', url, duration: 0, stalled: false })
  }

  play(): void {
    const g = this.graph
    if (g.url === null) return
    const ctx = holder().context
    if (ctx?.state === 'suspended') void ctx.resume().catch(() => {})
    if (g.status !== 'playing') this.change({ status: 'playing' })
    g.audio.play().catch((error: unknown) => {
      const name = error instanceof Error ? error.name : ''
      // A load() or pause() that came after: not a failure.
      if (name === 'AbortError' || g.status !== 'playing' || !g.audio.paused) return
      Object.assign(g, { status: 'paused' })
      if (!this.live) return
      this.notify()
      this.emit('error', { message: error instanceof Error ? error.message : String(error) })
    })
  }

  pause(): void {
    const g = this.graph
    if (g.status !== 'playing') return
    g.audio.pause()
    this.change({ status: 'paused' })
  }

  stop(): void {
    const g = this.graph
    g.audio.pause()
    try { g.audio.currentTime = 0 } catch { /* no media */ }
    this.change({ status: 'stopped' })
  }

  seek(seconds: number): void {
    const g = this.graph
    try { g.audio.currentTime = clamp(seconds, 0, g.duration > 0 ? g.duration : Infinity) } catch { /* no media */ }
    this.notify()
  }

  setVolume(volume: number): void {
    const v = clamp(volume, 0, 1)
    this.graph.gain.gain.value = v
    if (v !== this.graph.volume) this.change({ volume: v })
  }

  setBalance(balance: number): void {
    const b = clamp(balance, -1, 1)
    this.graph.left.gain.value = b > 0 ? 1 - b : 1
    this.graph.right.gain.value = b < 0 ? 1 + b : 1
    if (b !== this.graph.balance) this.change({ balance: b })
  }

  setEq(patch: Partial<AudioState['eq']>): void {
    const eq = mergeEq(this.graph.eq, patch)
    if (sameEq(eq, this.graph.eq)) return
    this.graph.eq = eq
    route(this.graph)
    this.notify()
  }

  analyser(): AnalyserNode { return this.graph.analyserNode }

  protected close(): void {
    const g = this.graph
    g.detach?.()
    g.detach = null
    g.audio.pause()
    g.audio.removeAttribute('src')
    g.audio.load()
    for (const node of [g.source, g.input, g.preamp, ...g.filters, g.balanceIn, g.left, g.right, g.merger, g.gain, g.analyserNode]) node.disconnect()
    const graphs = holder().graphs
    if (graphs.get(this.key) === g) graphs.delete(this.key)
    this.onClose(this)
  }
}

const NATIVE_FEATURES: AudioFeatures = { eq: false, balance: false, analyser: false }
const WEB_FEATURES: AudioFeatures = { eq: true, balance: true, analyser: true }

class AudioService extends Service implements AudioApi {
  static provide = 'audio'
  static author = 'dan'
  static tags = ['media']
  static version = __TILR_VERSION__

  declare state: { native: NativeAudio | null, web: Map<string, WebPlayer> }

  constructor(ctx: Context) {
    super(ctx, AudioService.provide)
    const channel = nativeChannel<NativeEvent>(HANDLER, EVENT)
    const native = channel ? new NativeAudio(body => channel.post(body)) : null
    this.state = { native, web: new Map() }

    if (channel && native) {
      ctx.effect(() => {
        const off = channel.listen(event => native.receive(event))
        native.start()
        return () => {
          off()
          native.release()
        }
      }, 'audio: native events')
      return
    }

    // The graphs a previous incarnation of this plugin left playing.
    for (const [key, graph] of holder().graphs) this.state.web.set(key, this.webPlayer(key, graph))
    // The first gesture lets a suspended AudioContext run.
    const resume = () => {
      const audio = holder().context
      if (audio?.state === 'suspended') void audio.resume().catch(() => {})
    }
    ctx.effect(() => {
      document.addEventListener('pointerdown', resume, true)
      document.addEventListener('keydown', resume, true)
      return () => {
        document.removeEventListener('pointerdown', resume, true)
        document.removeEventListener('keydown', resume, true)
      }
    }, 'audio: resume on a gesture')
    // The service going leaves the graphs playing; only its own objects let go of them.
    ctx.effect(() => () => {
      for (const player of this.state.web.values()) player.release()
      this.state.web.clear()
    }, 'audio: players')
  }

  get backend(): 'native' | 'web' {
    return this.state.native ? 'native' : 'web'
  }

  get features(): AudioFeatures {
    return { ...this.state.native ? NATIVE_FEATURES : WEB_FEATURES }
  }

  player(key: string): AudioPlayer {
    // this.ctx is the caller's context: the handle's listeners are its effects (not the player).
    return new Handle(this.core(String(key)), this.ctx)
  }

  players(): AudioPlayer[] {
    const { native, web } = this.state
    const cores: Core[] = native ? [...native.players.values()] : [...web.values()]
    return cores.map(core => new Handle(core, this.ctx))
  }

  private core(key: string): Core {
    const { native, web } = this.state
    if (native) return native.player(key)
    let player = web.get(key)
    if (!player) {
      const graphs = holder().graphs
      let graph = graphs.get(key)
      if (!graph) graphs.set(key, graph = build(key))
      player = this.webPlayer(key, graph)
      web.set(key, player)
    }
    return player
  }

  private webPlayer(key: string, graph: Graph): WebPlayer {
    return new WebPlayer(key, graph, closed => {
      if (this.state.web.get(closed.key) === closed) this.state.web.delete(closed.key)
    })
  }
}

export default AudioService satisfies TilrPluginClass
